using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using ModelContextProtocol;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddHttpClient("WeatherApi", client =>
{
    client.BaseAddress = new Uri("https://api.weather.gov/");
    client.DefaultRequestHeaders.Add("User-Agent", "McpServer/1.0");
});

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();

using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class WeatherTools
{
    [McpServerTool(Name = "get_forecast", Description = "Get weather forecast for a US location by latitude/longitude.")]
    public static async Task<string> GetForecast(
        IHttpClientFactory httpClientFactory,
        [McpServerToolParameter(Description = "Latitude of the location")] double latitude,
        [McpServerToolParameter(Description = "Longitude of the location")] double longitude)
    {
        var client = httpClientFactory.CreateClient("WeatherApi");

        // Resolve the grid endpoint for the coordinates
        var pointUrl = $"points/{latitude},{longitude}";
        var pointResponse = await client.GetFromJsonAsync<JsonElement>(pointUrl);
        var forecastUrl = pointResponse.GetProperty("properties").GetProperty("forecast").GetString()
            ?? throw new InvalidOperationException("No forecast URL returned");

        // Fetch the actual forecast
        var forecast = await client.GetFromJsonAsync<JsonElement>(forecastUrl);
        var periods = forecast.GetProperty("properties").GetProperty("periods");

        var results = periods.EnumerateArray()
            .Take(5)
            .Select(p => $"{p.GetProperty("name")}: {p.GetProperty("detailedForecast")}");

        return string.Join("\n\n", results);
    }

    [McpServerTool(Name = "get_alerts", Description = "Get active weather alerts for a US state (2-letter code).")]
    public static async Task<string> GetAlerts(
        IHttpClientFactory httpClientFactory,
        [McpServerToolParameter(Description = "Two-letter US state code, e.g. CA, NY")] string state)
    {
        var client = httpClientFactory.CreateClient("WeatherApi");

        var alerts = await client.GetFromJsonAsync<JsonElement>($"alerts/active/area/{state}");
        var features = alerts.GetProperty("features");

        if (features.GetArrayLength() == 0)
            return $"No active alerts for {state}.";

        var results = features.EnumerateArray()
            .Take(5)
            .Select(f =>
            {
                var props = f.GetProperty("properties");
                return $"[{props.GetProperty("severity")}] {props.GetProperty("headline")}";
            });

        return string.Join("\n", results);
    }
}

